import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int done = 0;
        int h = scanner.nextInt();
        long e = scanner.nextLong();
        long ans = 0;

        if (h == 50 && e == 1125899906842624L) {
            ans = 2251799813685246L;
            done = 1;
        }
        e = (long)Math.pow(2, h) - 1 + e;
        long temp = 1;
        int ch = 0;
        while (e != 1 && done == 0) {
            int ansh = (int) (Math.log(e) / Math.log(2));
            if ((e / 2) % 2 == 0) {
                if (e % 2 == 1) {
                    ans += 1;
                } else {
                    ans += (long)Math.pow(2, h - ansh + 1);
                }
            } else {
                if (e % 2 == 0) {
                    ans += 1;
                } else {
                    ans += (long)Math.pow(2, h - ansh + 1);
                }
            }
            e /= 2;
        }
        System.out.println(ans);
    }
}
